#define FSLABEL_MAX 64

/* Getting the Filesystem Label */
char label_buf[FSLABEL_MAX];
int fd = /* open device or mountpoint */;

if (ioctl(fd, FS_IOC_GETFSLABEL, label_buf) == 0) {
    // label_buf contains the null-terminated label
} else {
    // EOPNOTSUPP: FS does not support online labels
    // ENOTTY: fd does not refer to a filesystem
    // EINVAL: Bad parameters
}


/* Setting the Filesystem Label */
#define NEW_LABEL "Data_Store_v1"
int fd_rw = /* open O_RDWR */;

// Requires CAP_SYS_ADMIN privilege
strncpy(label_buf, NEW_LABEL, FSLABEL_MAX);

if (ioctl(fd_rw, FS_IOC_SETFSLABEL, label_buf) == -1) {
    // EPERM: Missing CAP_SYS_ADMIN
    // EROFS: fd opened O_RDONLY
    // EINVAL: Label too long (must be < FSLABEL_MAX)
}

close(fd_rw);
